                  <a class="chip-button" href="#editorial-content">Gift ideas</a>
                </div>
              </aside>
            </div>
          </div>
        </section>
      `;

      const SectionHeader = ({ id, eyebrow, title, description, link, linkText }) => `
        <div class="section-header">
          <div class="section-intro">
            <span class="eyebrow">${eyebrow}</span>
            <h2 id="${id}">${title}</h2>
            <p>${description}</p>
          </div>
          <a class="secondary-button" href="${link}">${linkText}</a>
        </div>
      `;

      const ProductCard = ({ name, category, price, originalPrice, rating, image, tags }) => `
        <article class="card">
          <div class="product-image" style="background-image: url('${image}');" role="img" aria-label="${name} product photo"></div>
          <div class="card-body">
            <div class="meta-row">
              <span class="tag">${category}</span>
              <span class="rating" aria-label="Rated ${rating} out of 5">${rating} ★</span>
