            <h3>${name}</h3>
            <p>Refined design with tactile materials and daily versatility.</p>
            <div class="price-row" aria-label="Pricing">
              <strong>${price}</strong>
              <s>${originalPrice}</s>
            </div>
            <div class="tag-row" aria-label="Product highlights">
              ${tags.map((tag) => `<span class="tag">${tag}</span>`).join("")}
            </div>
          </div>
        </article>
      `;

      const DealCard = ({ title, description, image, badge, cta }) => `
        <article class="deal-card">
          <div class="deal-image" style="background-image: url('${image}');" role="img" aria-label="${title} promotion image"></div>
          <div class="deal-body">
            <span class="pill">${badge}</span>
            <h3>${title}</h3>
            <p>${description}</p>
            <div class="hero-actions">
              <a class="primary-button" href="#newsletter">${cta}</a>
            </div>
          </div>
        </article>
      `;

      const EditorialCard = ({ title, description, image, meta }) => `
        <article class="editorial-card">
          <div class="editorial-image" style="background-image: url('${image}');" role="img" aria-label="${title} story artwork"></div>
          <div class="editorial-body">
            <span class="tag">${meta}</span>
            <h3>${title}</h3>
            <p>${description}</p>
            <div class="hero-actions">
              <a class="secondary-button" href="#newsletter">Read story</a>
            </div>
          </div>
        </article>
      `;

      const FeaturedProductsSection = () => `
        <section class="section shell" id="featured-products" aria-labelledby="featured-products-heading">
          ${SectionHeader({
            id: "featured-products-heading",
            eyebrow: "Featured products",
            title: "A considered assortment of bestsellers and new arrivals",
            description:
              "Shop pieces chosen for comfort, longevity, and everyday polish across apparel, accessories, and home.",
            link: "#deals",
            linkText: "See current deals"
          })}
          <div class="product-grid">
            ${featuredProducts.map(ProductCard).join("")}
          </div>
        </section>
      `;

      const DealsSection = () => `
        <section class="section shell" id="deals" aria-labelledby="deals-heading">
          ${SectionHeader({
            id: "deals-heading",
            eyebrow: "Deals",
            title: "Limited-time savings designed to feel worth acting on",
            description:
              "From bundle pricing to seasonal markdowns, these promotions bring value without compromising the edit.",
            link: "#newsletter",
            linkText: "Get deal alerts"
          })}
          <div class="deal-grid">
            ${deals.map(DealCard).join("")}
          </div>
        </section>
      `;

      const EditorialSection = () => `
        <section class="section shell" id="editorial-content" aria-labelledby="editorial-heading">
          ${SectionHeader({
            id: "editorial-heading",
            eyebrow: "Editorial content",
            title: "Stories that connect the products to a more intentional lifestyle",
            description:
              "Explore styling notes, home guidance, and buying insights created to make discovery feel thoughtful.",
            link: "#featured-products",
            linkText: "Browse products"
          })}
          <div class="spotlight-card">
            <div class="spotlight-body">
              <span class="eyebrow">Editor's spotlight</span>
              <h3>Inside the weekend reset collection</h3>
              <p>
                We paired breathable layers, soft neutrals, and elevated utility pieces into one cohesive edit built
                for easy mornings, polished errands, and quiet evenings at home.
              </p>
              <div class="hero-actions">
                <a class="primary-button" href="#featured-products">Shop the spotlight</a>
                <a class="secondary-button" href="#newsletter">Save this edit</a>
              </div>
            </div>
            <div class="spotlight-visual" role="img" aria-label="Curated lifestyle photography for editor spotlight"></div>
          </div>
          <div class="editorial-grid" style="margin-top: 1rem;">
            ${editorialStories.map(EditorialCard).join("")}
          </div>
        </section>
      `;

      const Newsletter = () => `
        <section class="shell" aria-labelledby="newsletter-heading">
          <div class="newsletter" id="newsletter">
            <div>
              <span class="pill">Stay in the loop</span>
              <h2 id="newsletter-heading">Get launch drops, deal reminders, and editorial picks in one weekly email.</h2>
              <p>No noise, just the best of the brand and the products customers are reaching for now.</p>
            </div>
            <form class="newsletter-form">
              <div class="newsletter-input">
                <label for="email">Email address</label>
                <input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="you@example.com"
                  autocomplete="email"
                  required
                  aria-describedby="email-help"
                />
                <p id="email-help" style="margin: 0.5rem 0 0; color: rgba(255, 255, 255, 0.74);">Weekly updates only. No spam.</p>
              </div>
              <button class="primary-button" type="submit">Subscribe</button>
            </form>
            <p id="newsletter-status" aria-live="polite" style="margin: 0; color: rgba(255, 255, 255, 0.9);"></p>
          </div>
        </section>
      `;

      const Footer = () => `
        <footer class="site-footer">
          <div class="shell footer-bar">
            <span>Northstar Collective</span>
            <span>Elevated retail for everyday life.</span>
          </div>
        </footer>
      `;

      const App = () => `
        <div id="top">
          ${Header()}
          <main id="main-content">
            ${Hero()}
            ${FeaturedProductsSection()}
            ${DealsSection()}
            ${EditorialSection()}
            ${Newsletter()}
          </main>
          ${Footer()}
        </div>
      `;

      document.getElementById("app").innerHTML = App();

      const newsletterForm = document.querySelector(".newsletter-form");
      const newsletterInput = document.getElementById("email");
      const newsletterStatus = document.getElementById("newsletter-status");

      newsletterForm.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!newsletterInput.reportValidity()) {
          newsletterInput.focus();
          return;
        }

        newsletterStatus.textContent = "Thanks for subscribing. Your first edit lands soon.";
        newsletterForm.reset();
      });
    </script>
  </body>
</html>
