       button:focus-visible,
       input:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: 3px;
       }

       .skip-link {
         position: absolute;
         top: 0;
         left: 1rem;
         transform: translateY(-140%);
         padding: 0.85rem 1.1rem;
         background: var(--text);
         color: #ffffff;
         border-radius: 0 0 var(--radius-sm) var(--radius-sm);
         z-index: 100;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       .shell {
         width: min(calc(100% - 2rem), var(--page-width));
         margin: 0 auto;
       }

       .site-header {
         position: sticky;
         top: 0;
         z-index: 20;
         backdrop-filter: blur(14px);
         background: rgba(245, 247, 251, 0.86);
         border-bottom: 1px solid rgba(214, 219, 230, 0.8);
       }

       .header-bar {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         min-height: 78px;
       }

       .brand {
         display: inline-flex;
         align-items: center;
         gap: 0.85rem;
         font-weight: 800;
         letter-spacing: -0.04em;
       }

       .brand-mark {
         display: inline-grid;
         place-items: center;
         width: 2.5rem;
         height: 2.5rem;
         border-radius: 0.9rem;
         background: linear-gradient(135deg, var(--brand), #7c93ff);
         color: #ffffff;
         box-shadow: 0 12px 24px rgba(34, 81, 255, 0.22);
       }

       .header-nav ul {
         display: flex;
         flex-wrap: wrap;
         align-items: center;
         justify-content: center;
         gap: 0.5rem;
         margin: 0;
         padding: 0;
         list-style: none;
       }

       .header-nav a {
         display: inline-flex;
         align-items: center;
         min-height: 2.75rem;
         padding: 0 1rem;
         border-radius: 999px;
         color: var(--text-soft);
         font-weight: 600;
       }

       .header-nav a:hover,
       .header-nav a:focus-visible {
         background: rgba(255, 255, 255, 0.85);
         color: var(--text);
       }

       .header-actions {
         display: flex;
         align-items: center;
         gap: 0.75rem;
       }

       .search-pill,
       .chip-button,
       .primary-button,
       .secondary-button {
         display: inline-flex;
         align-items: center;
         justify-content: center;
         min-height: 2.9rem;
         padding: 0 1rem;
         border: 1px solid transparent;
         border-radius: 999px;
         font: inherit;
         font-weight: 700;
       }

       .search-pill,
       .secondary-button,
       .chip-button {
         background: rgba(255, 255, 255, 0.9);
         color: var(--text);
         border-color: var(--line);
       }

       .primary-button {
         background: var(--text);
         color: #ffffff;
         box-shadow: 0 14px 28px rgba(17, 24, 39, 0.18);
       }

       .primary-button:hover,
       .primary-button:focus-visible,
       .secondary-button:hover,
       .secondary-button:focus-visible,
       .chip-button:hover,
       .chip-button:focus-visible {
         transform: translateY(-1px);
       }

       .hero {
         padding: 2.5rem 0 1.5rem;
       }

       .hero-grid {
         display: grid;
         grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
         gap: 1.25rem;
       }

       .hero-card,
       .hero-side-card,
       .card,
       .deal-card,
       .editorial-card,
       .spotlight-card {
         background: rgba(255, 255, 255, 0.92);
         border: 1px solid rgba(214, 219, 230, 0.92);
         border-radius: var(--radius-lg);
         box-shadow: var(--shadow);
       }

       .hero-card {
         overflow: hidden;
         position: relative;
         display: grid;
         grid-template-columns: minmax(0, 1.1fr) minmax(260px, 0.9fr);
         min-height: 440px;
       }

       .hero-copy {
         padding: clamp(1.75rem, 3vw, 3rem);
         display: flex;
         flex-direction: column;
         justify-content: center;
       }

       .eyebrow,
       .pill {
         display: inline-flex;
         align-items: center;
         gap: 0.45rem;
         width: fit-content;
         padding: 0.45rem 0.8rem;
         border-radius: 999px;
         font-size: 0.88rem;
         font-weight: 700;
       }

       .eyebrow {
         background: rgba(34, 81, 255, 0.1);
         color: var(--brand-strong);
       }

       .pill {
         background: rgba(15, 139, 98, 0.12);
         color: var(--success);
       }

       h1,
       h2,
       h3 {
         margin: 0;
         letter-spacing: -0.05em;
       }
